type Props={params:Promise<{subject:string;year:string;medium:string}>};
export function generateStaticParams(){return papers.map(p=>({subject:p.subject,year:String(p.year),medium:p.medium}))}
export async function generateMetadata({params}:Props):Promise<Metadata>{
 const x=await params,p=getPaper(x.subject,Number(x.year),x.medium),s=getSubject(x.subject);if(!p||!s)return{};
 const kind=p.paperUrl?"Past Paper":p.answerType==="evaluation-report"?"Evaluation Report":"Marking Scheme";const title=`${p.displayYear} O/L ${s.en} ${kind} – ${mediumNames[p.medium]}`;
 const description=p.paperUrl?(p.hasMarkingScheme?`Download the official ${p.displayYear} G.C.E. O/L ${s.en} past paper and answers in ${mediumNames[p.medium]}.`:`Download the official ${p.displayYear} G.C.E. O/L ${s.en} past paper in ${mediumNames[p.medium]}.`):`Download the official ${p.displayYear} G.C.E. O/L ${s.en} ${kind.toLowerCase()} with answers in ${mediumNames[p.medium]}.`;
 return {title,description,alternates:{canonical:paperPath(p)},openGraph:{title,description}};
}
